import React from 'react';
import { Link, useLocation } from 'react-router-dom';
import { Facebook, Instagram, Youtube, Linkedin } from 'lucide-react';
import Logo from './Logo';
import styles from './Footer.module.css';

// Official X (formerly Twitter) vector icon
function XIcon({ size = 15 }) {
  return (
    <svg width={size} height={size} viewBox="0 0 24 24" fill="currentColor" aria-hidden="true" style={{ display: 'block' }}>
      <path d="M18.244 2.25h3.308l-7.227 8.26 8.502 11.24H16.17l-5.214-6.817L4.99 21.75H1.68l7.73-8.835L1.254 2.25H8.08l4.713 6.231zm-1.161 17.52h1.833L7.084 4.126H5.117z" />
    </svg>
  );
}

const LINKS = [
  { label: 'Buy',          to: '/search?listingType=Sell' },
  { label: 'Rent',         to: '/search?listingType=Rent' },
  { label: 'Commercial',   to: '/search?buildingType=Commercial' },
];

const SOCIAL = [
  {
    icon: Facebook,
    label: 'Facebook',
    url: 'https://www.facebook.com/profile.php?id=61594013548834',
  },
  {
    icon: Youtube,
    label: 'YouTube',
    url: 'https://www.youtube.com/@Probridgeofficial',
  },
  {
    icon: Instagram,
    label: 'Instagram',
    url: 'https://www.instagram.com/probridgeofficial/?hl=en',
  },
  {
    icon: XIcon,
    label: 'X (Twitter)',
    url: 'https://x.com/Probbridge/status/2114328176268849582?s=20',
  },
  {
    icon: Linkedin,
    label: 'LinkedIn',
    url: 'https://www.linkedin.com/in/probridge-hr-714b19432/?isSelfProfile=true',
  },
];

export default function Footer() {
  const location = useLocation();

  // Company details section only appears on the home screen ('/')
  if (location.pathname !== '/') {
    return null;
  }

  return (
    <footer className={styles.footer}>
      <div className={styles.inner}>
        {/* Brand */}
        <div className={styles.brand}>
          <Link to="/" className={styles.footerLogoLink} title="ProBridge">
            <Logo size="lg" showTagline={true} />
          </Link>
        </div>

        {/* Quick Links */}
        <div className={styles.links}>
          {LINKS.map(l => (
            <Link key={l.label} to={l.to} className={styles.link}>{l.label}</Link>
          ))}
        </div>

        {/* Contact */}
        <div className={styles.contact}>
          <div className={styles.contactTitle}>Contact Us</div>
          <a href="https://www.probridge.co.in" target="_blank" rel="noopener noreferrer" className={styles.contactItem}>www.probridge.co.in</a>
          <a href="tel:+919176663200" className={styles.contactItem}>+91 9176663200</a>
        </div>
      </div>

      {/* Bottom Bar */}
      <div className={styles.bottomBar}>
        <div className={styles.bottomInner}>
          <span className={styles.copy}>© {new Date().getFullYear()} Probridge Pvt. Ltd. All rights reserved.</span>
          <div className={styles.social}>
            {SOCIAL.map(s => {
              const Icon = s.icon;
              return (
                <a
                  key={s.label}
                  href={s.url}
                  target="_blank"
                  rel="noopener noreferrer"
                  className={styles.socialBtn}
                  aria-label={s.label}
                  title={s.label}
                >
                  <Icon size={16} />
                </a>
              );
            })}
          </div>
        </div>
      </div>
    </footer>
  );
}
